// Deterministic static template build; downloads only the pinned npm package with --fetch.
const fs = require('node:fs');
const path = require('node:path');
const crypto = require('node:crypto');
const zlib = require('node:zlib');
const root = path.resolve(__dirname, '..');
const version = '4.2.1';
const integrity = 'YyAXyvnmjTbR4bHQRLzex3CuINCDlQnBqoSYyjJwTP2x9jDLuKDzy7aKUl0hgx3uhcl7xzg32agn5vlie6HIlQ==';
const vendor = path.join(root, 'vendor', 'jspdf-' + version + '.umd.min.js');
async function build() {
  if (process.argv.includes('--fetch')) {
    const response = await fetch('https://registry.npmjs.org/jspdf/-/jspdf-' + version + '.tgz');
    if (!response.ok) throw new Error('Pinned library download failed: HTTP ' + response.status);
    const archive = Buffer.from(await response.arrayBuffer());
    if (crypto.createHash('sha512').update(archive).digest('base64') !== integrity) throw new Error('Library integrity mismatch');
    const tar = zlib.gunzipSync(archive, { maxOutputLength: 40 * 1024 * 1024 });
    const wanted = new Map([['package/dist/jspdf.umd.min.js', vendor],
      ['package/LICENSE', path.join(root, 'vendor', 'jspdf-LICENSE.txt')]]);
    fs.mkdirSync(path.dirname(vendor), { recursive: true });
    for (let offset = 0; offset + 512 <= tar.length;) {
      const name = tar.subarray(offset, offset + 100).toString().replace(/\0.*$/, '');
      if (!name) break;
      const size = parseInt(tar.subarray(offset + 124, offset + 136).toString().replace(/\0.*$/, '').trim(), 8);
      if (!Number.isSafeInteger(size) || size < 0 || offset + 512 + size > tar.length) throw new Error('Invalid package archive');
      if (wanted.has(name)) {
        fs.writeFileSync(wanted.get(name), tar.subarray(offset + 512, offset + 512 + size));
        wanted.delete(name);
      }
      offset += 512 + Math.ceil(size / 512) * 512;
    }
    if (wanted.size) throw new Error('Pinned package is missing required files');
  }
  const library = fs.readFileSync(vendor, 'utf8').replace(/^\/\/# sourceMappingURL=.*$/gm, '');
  const module = fs.readFileSync(path.join(root, 'pettycash-receipts.js'), 'utf8');
  // Keep host AMD/CommonJS globals intact while forcing the browser UMD export.
  let source = '(function(define,module,exports){\n' + library +
    '\n}).call(window,undefined,undefined,undefined);\n;\n' + module;
  if (source.includes('{% endraw %}')) throw new Error('Unexpected Liquid terminator');
  source = source.replace(/<\/script/gi, '<\\/script');
  const template = '<!-- Generated by scripts/build_receipt_template.cjs. jsPDF ' + version +
    ' (MIT); source and license in vendor/. Paste complete file into Web Template Petty Cash Receipts. -->\n' +
    '{% raw %}\n<script>\n' + source + '\n</script>\n{% endraw %}\n';
  fs.writeFileSync(path.join(root, 'Petty Cash Receipts.html'), template);
  console.log('Built Petty Cash Receipts.html (' + Buffer.byteLength(template) + ' bytes); jsPDF ' + version);
}
build().catch(error => { console.error(error.message); process.exitCode = 1; });
